package com.streamcraft.core.runtime;
import java.io.*; import java.util.*; import org.apache.flink.core.io.SimpleVersionedSerializer;
final class InfluxDbSourceEnumeratorStateSerializer implements SimpleVersionedSerializer<InfluxDbSourceEnumeratorState>{
 private static final int VERSION=3; private final InfluxDbSourceSplitSerializer serializer=new InfluxDbSourceSplitSerializer(); public int getVersion(){return VERSION;}
 public byte[] serialize(InfluxDbSourceEnumeratorState s)throws IOException{ByteArrayOutputStream b=new ByteArrayOutputStream();try(DataOutputStream o=new DataOutputStream(b)){o.writeByte(VERSION);List<InfluxDbSourceSplit> p=s==null?List.of():s.pendingSplits();o.writeInt(p.size());for(InfluxDbSourceSplit x:p){byte[] z=serializer.serialize(x);o.writeInt(z.length);o.write(z);}}return b.toByteArray();}
 public InfluxDbSourceEnumeratorState deserialize(int v,byte[] d)throws IOException{if(v<1||v>VERSION||d==null)throw new IOException("Invalid InfluxDB enumerator state.");try(DataInputStream i=new DataInputStream(new ByteArrayInputStream(d))){if(i.readUnsignedByte()!=v)throw new IOException("Invalid InfluxDB enumerator state marker.");List<InfluxDbSourceSplit> p=new ArrayList<>();if(v<VERSION){if(i.readBoolean())p.add(read(i));}else{int n=i.readInt();if(n<0||n>i.available())throw new IOException("Invalid InfluxDB split count.");for(int k=0;k<n;k++)p.add(read(i));}if(i.available()!=0)throw new IOException("Trailing bytes in InfluxDB enumerator state.");return new InfluxDbSourceEnumeratorState(p);}}
 private InfluxDbSourceSplit read(DataInputStream i)throws IOException{int n=i.readInt();if(n<0||n>i.available())throw new IOException("Invalid InfluxDB split length.");byte[] b=i.readNBytes(n);if(b.length!=n)throw new IOException("Truncated InfluxDB split.");return serializer.deserialize(b[0]&255,b);}
}
